        "content": "### 1. Правила безопасности при эксплуатации и обслуживании СВТ\nТехническое обслуживание средств вычислительной техники сопряжено с факторами производственной опасности: высокое напряжение сети 220/230 В, заряженные конденсаторы высокой емкости в блоках питания, вращающиеся лопасти кулеров и опасность статического разряда:\n- **Электробезопасность**:\n  * Категорически запрещается производить ремонт, чистку от пыли или замену комплектующих при включенном кабеле питания.\n  * Первичная высоковольтная цепь импульсных блоков питания (БП) содержит сглаживающие конденсаторы фильтра с напряжением до **350–400 В**. Перед вмешательством необходимо выждать не менее 5 минут для их саморазряда через резисторы утечки или принудительно разрядить через резистор 1 кОм.\n  * Все розетки и рабочие места обязаны быть заземлены по системе TN-S / TN-C-S с отдельным защитным проводником PE.\n- **Антистатическая защита (ESD — Electrostatic Discharge)**:\n  * Человек в сухом помещении накапливает электростатический заряд до 10–15 кВ. Для пробоя подзатворного диэлектрика современных транзисторов процессора или видеопамяти достаточно импульса всего в **50–100 В**.\n  * Работы по обслуживанию материнских плат, планок ОЗУ и видеокарт выполняются на антистатическом заземленном коврике с использованием антистатического браслета с токоограничивающим резистором 1 МОм.\n\n### 2. Пожарная безопасность в серверных и вычислительных залах\n- При возникновении возгорания немедленно обесточить аппаратуру аварийным рубильником.\n- Категорически запрещено тушить электронику водой или пенными огнетушителями (опасность смертельного поражения током и необратимого короткого замыкания аппаратуры).\n- Разрешено использовать только углекислотные огнетушители (ОУ-2, ОУ-5) или автоматические газовые системы пожаротушения (хладон, Novec 1230), не оставляющие токопроводящих следов.\n\n### 3. Цели и задачи учебной дисциплины\nДисциплина формирует профессиональные компетенции техника-электроника:\n1. Освоение методов аппаратного и программного диагностирования вычислительных узлов.\n2. Изучение методологии поиска и локализации скрытых дефектов и сбоев.\n3. Проведение регламентного профилактического технического обслуживания (ТО) и компонентного ремонта.",
        "intuitSourceRef": "https://intuit.ru/studies/courses/tesvt"
