        "content": "### 1. Понятие и цели технического обслуживания СВТ\nТехническая эксплуатация СВТ представляет собой совокупность процессов ввода в эксплуатацию, поддержания работоспособности в заданных режимах, проведения технического обслуживания, хранения и ремонта.\nОсновная цель ТО — обеспечение максимальной готовности парка ЭВМ к выполнению функциональных задач при минимальных финансовых и временных затратах.\n\n### 2. Классификация видов технического обслуживания\nСогласно ГОСТ 18322-78, техническое обслуживание подразделяется на следующие категории:\n1. **Регламентированное ТО (Плановое)**: Выполняется с периодичностью и в объеме, установленными в эксплуатационной документации завода-изготовителя, независимо от технического состояния оборудования:\n   - Ежедневное (контрольный осмотр, проверка кабелей, проверка индикаторов).\n   - Ежемесячное / полугодовое ТО (глубокая очистка от пыли, проверка подшипников вентиляторов, контроль питающих напряжений, обновление баз безопасности).\n2. **ТО по фактическому состоянию (Condition-Based)**: Контроль параметров проводится с помощью встроенных датчиков (температура, смарт-атрибуты накопителей, уровень пульсаций БП). Ремонт или замена узлов осуществляется только тогда, когда параметры приближаются к критической границе.\n3. **Корректирующее ТО (Аварийный ремонт / Unscheduled)**: Проводится по факту возникновения отказа или явной неисправности узла.\n\n### 3. Технологический цикл профилактического обслуживания ПК\n- Обесточивание и снятие статического заряда.\n- Вскрытие корпуса и продувка от пыли сжатым сухим воздухом или компрессором (давление не более 2-3 атм).\n- Принудительная фиксация крыльчаток вентиляторов при продувке (предотвращение генерации обратной ЭДС в материнскую плату и повреждения гидродинамических подшипников).\n- Замена термоинтерфейса (термопасты) на процессоре и видеокарте с предварительным удалением засохшего слоя изопропиловым спиртом.\n- Протяжка винтовых соединений и проверка надежности разъемов питания SATA, ATX, PCIe.",
        "intuitSourceRef": "https://intuit.ru/studies/courses/tesvt"
