        "content": "### 1. Инженерная инфраструктура центров обработки данных (ЦОД)\nВычислительный центр корпоративного уровня представляет собой комплекс аппаратных средств и инженерных систем жизнеобеспечения:\n1. **Система прецизионного кондиционирования (HVAC)**:\n   - Серверные стойки высокой плотности выделяют от 5 до 30 кВт тепла на шкаф.\n   - Используется разделение на изолированные «холодные» коридоры (куда кондиционеры подают охлажденный воздух через перфорированный фальшпол) и «горячие» коридоры (откуда нагретый серверами воздух забирается под фальшпотолок).\n   - Влажность строго поддерживается в диапазоне 45–55% для подавления электростатических разрядов.\n2. **Система гарантированного электроснабжения (СГЭ)**:\n   - Архитектура On-line ИБП: переменный ток сети выпрямляется в постоянный, фильтруется, питает аккумуляторы и непрерывно регенерируется инвертором в идеальную синусоиду без разрыва фазы (время переключения = 0 мс).\n   - Автоматический ввод резерва (АВР) запускает Дизель-Генераторную Установку (ДГУ) при пропадании городского ввода в течение 30–60 секунд.\n\n### 2. Регламент обслуживания серверного оборудования\n- Проверка дублированных блоков питания (Redundant Power Supply 1+1).\n- Горячая замена накопителей (Hot-Swap) при срабатывании индикаторов Predictive Failure в дисковых корзинах.\n- Мониторинг аппаратных логов через выделенные контроллеры удаленного управления (IPMI / iLO / iDRAC).\n- Проверка воздушных фильтров и очистка радиаторов охлаждения тепловых трубок процессоров Xeon/EPYC.",
        "intuitSourceRef": "https://intuit.ru/studies/courses/tesvt"
