      "synopsis": {
        "summary": "Математические и инженерные основы тестирования комбинационных и последовательностных цифровых схем. Модели неисправностей логических элементов: константные дефекты Stuck-at-0 / Stuck-at-1. Методы синтеза минимальных проверяющих и диагностических тестов. D-алгоритм Рота.",
        "keyPoints": [
          "Тест цифрового устройства — совокупность входных двоичных векторов и эталонных выходных реакций исправной схемы.",
          "Проверяющий тест: определяет факт наличия хотя бы одного дефекта («годен / не годен»).",
          "Диагностический тест: точно указывает место и тип неисправности (локализует дефектный логический элемент или линию связи).",
          "Модель константных неисправностей (КН): вход или выход логического вентиля принудительно замкнут на логический 0 ($\\equiv 0$) или на 1 ($\\equiv 1$).",
          "Активизация пути и D-алгоритм: подача чувствительного сигнала $D$ ($1$ в исправной, $0$ в неисправной) и его продвижение через тракт схемы к выходу.",
          "Коэффициент покрытия дефектов (Fault Coverage): процент обнаруживаемых неисправностей от общего числа возможных дефектов."
        ],
        "content": "### 1. Модели неисправностей цифровых узлов\nПри тестировании интегральных микросхем физические дефекты кремния (обрывы металлизации, пробои изоляции) абстрагируют в виде логических моделей:\n1. **Одиночные константные неисправности (ОКН / Single Stuck-At Faults)**:\n   - $s-a-0$ (Stuck-At-Zero, константа 0): проводник постоянно имеет уровень логического 0 независимо от схемы управления.\n   - $s-a-1$ (Stuck-At-One, константа 1): проводник постоянно имеет уровень логической 1.\n2. **Неисправности типа замыкания (Bridging faults)**: Случайное перемыкание соседних проводников шины с возникновением логического И или ИЛИ (Wired-AND / Wired-OR).\n3. **Задержечные дефекты (Delay Faults)**: Схема логически верна, но время распространения сигнала превышает тактовый период, нарушая тайминги Setup/Hold.\n\n### 2. Синтез проверяющих тестов (D-алгоритм Рота)\nДля обнаружения неисправности на линии $L$ необходимо выполнить два условия:\n1. **Активация дефекта**: На линию $L$ подается значение, противоположное неисправности. Для проверки на $s-a-0$ подается логическая 1 (возникает различие $D = 1/0$).\n2. **Транспортировка (проталкивание) ошибки к внешнему выходу**: На входы остальных вентилей по пути прохождения накладываются разрешающие уровни:\n   - Для элемента «И / И-НЕ» на соседние входы подаются **единицы**.\n   - Для элемента «ИЛИ / ИЛИ-НЕ» на соседние входы подаются **нули**.\n   - Если на выходе наблюдается инверсия ожидаемого сигнала, дефект обнаружен!\n\n### 3. Диагностические матрицы неисправностей\nРезультаты прогона тестовых векторов $T_1, T_2, \\dots, T_m$ заносятся в булеву матрицу покрытия: строки соответствуют тестам, столбцы — дефектам. Минимизация матрицы методами теории графов позволяет получить минимальный проверяющий набор тестов.",
        "intuitSourceRef": "https://intuit.ru/studies/courses/tesvt"
      },
