      "hours": 2,
      "sectionId": "sec-maint-3",
      "shortDescription": "Аппаратные методы обнаружения ошибок, сторожевые схемы, схемы контроля питания (Power Good), пороговые компараторы, избыточное кодирование.",
      "synopsis": {
        "summary": "Принципы аппаратного контроля функционирования вычислительных узлов в режиме реального времени. Формирование сигнала готовности питания Power Good (PG / PWR_OK). Пороговые детекторы напряжений, схемы сброса при включении (Power-On Reset — POR) и сторожевые генераторы таймингов.",
        "keyPoints": [
          "Аппаратный контроль работает непрерывно на схемном уровне, не расходуя производительность центрального процессора.",
          "Сигнал Power Good (PWR_OK): блок питания выставляет лог. 1 (+5 В) только тогда, когда все выходные напряжения стабилизировались в пределах $\\pm 5\\%$ в течение 100–500 мс.",
          "Схема Power-On Reset (POR): удерживает процессор в сбросе до момента полной стабилизации внутренних напряжений и запуска кварцевого резонатора.",
          "Аппаратный компаратор питающих напряжений: при мгновенной просадке напряжения сети схема инициирует немаскируемое прерывание NMI для экстренного сохранения состояния ОС.",
          "Контроль четности шин и памяти: аппаратные свертки на элементах XOR, регистрирующие сбои каждого байта за 1 такт."
        ],
        "content": "### 1. Архитектура аппаратного контроля питания: сигнал Power Good\nПроцессор и логические микросхемы не могут корректно функционировать при плавающем или заниженном напряжении питания:\n- При включении ПК импульсный блок питания плавно выходит на рабочий режим в течение десятков миллисекунд.\n- На сером проводе разъема ATX присутствует сигнал **Power Good (PWR_OK)**:\n  * В момент старта $PWR\\_OK = 0$ В. Материнская плата удерживает процессор в состоянии аппаратного сброса (`RESET# = 0`).\n  * Встроенный компаратор микросхемы супервизора БП (например, WT7527) непрерывно измеряет напряжения $+12V$, $+5V$, $+3.3V$.\n  * Если все шины стабилизировались в пределах допуска $\\pm 5\\%$, супервизор с задержкой в **100–500 мс** поднимает $PWR\\_OK$ в логическую единицу ($+5$ В).\n  * Материнская плата снимает сброс с процессора, инициируя исполнение микрокода POST.\n  * Если при работе напряжение сети просаживается и хотя бы одна линия падает ниже нормы, БП сбрасывает $PWR\\_OK$ в ноль за 1 мс до отключения напряжений, защищая накопители от разрушения файловой системы.\n\n### 2. Схемы Power-On Reset (POR) и супервизоры питания\n- Специализированные микросхемы-супервизоры (типа MAX811, TPS3823) содержат прецизионный источник опорного напряжения и компаратор.\n- Они формируют калиброванный импульс сброса длительностью 200 мс при каждом включении питания или кратковременном провале напряжения (Brownout).",
        "intuitSourceRef": "https://intuit.ru/studies/courses/tesvt"
      },
