        "content": "### 1. Измерительный комплекс сервисного инженера СВТ\nКачественная диагностика цифровой и силовой электроники невозможна без специализированных контрольно-измерительных приборов:\n1. **Цифровой запоминающий осциллограф (DSO)**:\n   - Измерение амплитуды, длительности и формы импульсов тактовых генераторов и линий передачи.\n   - Закрытый вход (AC Coupling): измерение высокочастотных пульсаций (Ripple Voltage) на конденсаторах силовых шин питания под нагрузкой (норма пульсаций для линии 12 В — не более 120 мВ, для шин 5 В и 3.3 В — не более 50 мВ).\n2. **Логический анализатор**:\n   - В отличие от 2-канального осциллографа, логический анализатор имеет от 8 до 34 каналов.\n   - Фиксирует только дискретные логические уровни (0 и 1), сохраняя миллионы отсчетов в глубокую память.\n   - Аппаратные декодеры протоколов «на лету» транслируют временные диаграммы в читаемые байты команд интерфейсов (SPI, I2C, UART).\n3. **Регулируемый лабораторный блок питания (ЛБП)**:\n   - Незаменим для поиска коротких замыканий (КЗ) методом подачи низкого напряжения: при наличии КЗ по шине питания процессора выставляется напряжение **1.0 В** с ограничением тока **2–3 А**. Нагревающийся дефектный керамический конденсатор или пробитый мосфет мгновенно локализуется тепловизором без риска сжечь кристалл процессора.\n4. **Ремонтные паяльные комплексы**:\n   - Нижний инфракрасный или термовоздушный преднагреватель платы: нагрев всего текстолита до 130–150 °C исключает термоудар и деформацию многослойной печатной платы при монтаже компонентов.",
