        "content": "### Цель практической работы\nИзучить принципы функционирования цифрового логического анализатора, освоить методику настройки условий синхронизации и аппаратного декодирования последовательных протоколов при локализации сбоев аппаратуры СВТ.\n\n### Ключевые этапы выполнения\n1. **Подключение прибора в среде Proteus**:\n   - Включение виртуального логического анализатора `LOGIC ANALYSER` к шине обмена между микроконтроллером и микросхемой часов реального времени RTC.\n2. **Конфигурация параметров захвата**:\n   - Выбор частоты квантования (Sampling Rate) — не менее чем в 4–5 раз выше тактовой частоты шины.\n   - Настройка триггера `Trigger Pattern` на обнаружение стартового условия I2C.\n3. **Захват и расшифровка сигналов**:\n   - Анализ корректности бита подтверждения `ACK`.\n   - Обнаружение паразитных импульсных помех (Glitches) на линии синхронизации.\n4. **Составление протокола измерений**:\n   - Сопоставление декодированных байтов с картой регистров опрашиваемого устройства.",
