      "sectionId": "sec-maint-4",
      "shortDescription": "Теория помехоустойчивого кодирования, кодовое расстояние Хэмминга d_min, код Хэмминга (7,4) и (72,64), циклическое кодирование CRC, синдромное декодирование.",
      "synopsis": {
        "summary": "Основы теории помехоустойчивого и корректирующего кодирования в вычислительных системах. Кодовое расстояние Хэмминга d_min. Обнаруживающая и исправляющая способность кодов. Математический аппарат кода Хэмминга с исправлением одиночных ошибок (SEC) и обнаружением двойных (DED). Циклические коды CRC.",
        "keyPoints": [
          "Кодовое расстояние Хэмминга $d_{min}$ — минимальное число позиций, в которых отличаются любые два разрешенных кодовых слова.",
          "Для обнаружения $r$ ошибок требуется кодовое расстояние: $d_{min} \\ge r + 1$.",
          "Для исправления $s$ ошибок требуется кодовое расстояние: $d_{min} \\ge 2s + 1$.",
          "Для одновременного исправления $s$ ошибок и обнаружения $r$ ошибок ($r > s$): $d_{min} \\ge s + r + 1$.",
          "Код Хэмминга: контрольные биты размещаются на позициях степеней двойки ($1, 2, 4, 8, 16, \\dots$). Синдром ошибки прямо указывает двоичный номер сбойного бита!",
          "Промышленный стандарт памяти серверов SECDED (72, 64): к 64 битам данных добавляется 8 контрольных бит Хэмминга."
        ],
        "content": "### 1. Метрика Хэмминга и корректирующая способность кодов\nОбычное двоичное кодирование безызбыточно: любое искажение одного бита превращает разрешенное слово в другое разрешенное слово, делая обнаружение ошибки невозможным ($d_{min} = 1$).\nВведение избыточных (контрольных) бит раздвигает разрешенные кодовые комбинации в $n$-мерном пространстве:\n- Если $d_{min} = 2$ (код с контролем четности): одиночная ошибка переводит слово в запрещенное ($r = 1$), но исправление невозможно.\n- Если $d_{min} = 3$ (код Хэмминга): любая одиночная ошибка переводит кодовое слово в сферу радиуса 1 вокруг истинного слова, позволяя однозначно восстановить исходное значение ($s = 1$).\n- Если $d_{min} = 4$ (код Хэмминга с общим битом паритета — SECDED): одиночные ошибки исправляются, а двойные — гарантированно обнаруживаются без ложного исправления.\n\n### 2. Алгоритм построения кода Хэмминга (7, 4)\nКодирует 4 бита данных ($D_3, D_5, D_6, D_7$) тремя контрольными битами ($P_1, P_2, P_4$):\n- Позиции контрольных бит: $1 = 2^0$, $2 = 2^1$, $4 = 2^2$.\n- Контрольный бит $P_1$ проверяет биты с единицей в нулевом разряде номера позиции ($1, 3, 5, 7$):\n  $$P_1 = D_3 \\oplus D_5 \\oplus D_7$$\n- Контрольный бит $P_2$ проверяет позиции ($2, 3, 6, 7$):\n  $$P_2 = D_3 \\oplus D_6 \\oplus D_7$$\n- Контрольный бит $P_4$ проверяет позиции ($4, 5, 6, 7$):\n  $$P_4 = D_5 \\oplus D_6 \\oplus D_7$$\n\n### 3. Синдромное декодирование\nНа приемном конце вычисляется 3-битный вектор синдрома:\n$$S = (S_2, S_1, S_0)$$\n- Если $S = 000_2$ — ошибок нет, данные истинны.\n- Если $S \\neq 0$, числовое значение синдрома **в точности равно порядковому номеру ошибочного бита**!\n- Для исправления ошибки достаточно инвертировать бит с номером $S$:\n  $$\\text{Bit}[S] = \\text{Bit}[S] \\oplus 1$$",
        "intuitSourceRef": "https://intuit.ru/studies/courses/tesvt"
      },
