        "content": "### Цель лабораторной работы\nИзучить принципы аппаратной реализации контроля четности при передаче цифровых массивов между регистрами СВТ, экспериментально определить обнаруживающую способность метода.\n\n### Ключевые этапы выполнения\n1. **Схемотехника в Proteus**:\n   - Передающий регистр `74HC273`, микросхема контроля четности `74HC280 (9-bit Parity Generator)`.\n   - Приемный регистр и схема сравнения паритета.\n2. **Проведение экспериментов**:\n   - Подача байтов с четным и нечетным числом единиц.\n   - Контроль формирования бита `Even / Odd Parity`.\n3. **Имитация сбоев канала связи**:\n   - Инверсия одного бита данных: фиксация загорания аварийного светодиода `PARITY ERROR`.\n   - Одновременная инверсия двух бит: подтверждение теоретического вывода о необнаружении двойной симметричной ошибки.",
