        "content": "### 1. Схемный контроль процессорных кэшей и архитектура MCA\nСовременные процессоры содержат десятки мегабайт статичной кэш-памяти SRAM (L1, L2, L3), занимающей до $70\\%$ площади кристалла. При плотности размещения миллиардов транзисторов вероятность сбоя ячейки от внешних космических лучей чрезвычайно высока:\n- Кэши L1 Instruction защищаются битом паритета (при сбое строка просто аннулируется и перезагружается из L2).\n- Кэши данных L1 Data, L2 и L3 защищены аппаратным **ECC (SECDED)**:\n  * Одиночный сбой исправляется за 0 тактов на лету аппаратным дешифратором Хэмминга.\n  * Архитектура **MCA (Machine Check Architecture)** фиксирует адрес поврежденной ячейки в банке регистров `IA32_MCi_ADDR` и инкрементирует счетчик `Corrected Error Count`.\n  * Если число сбоев одной ячейки превышает порог, микрокод процессора аппаратно отключает дефектную строку кэша (Row Retirement), предотвращая дальнейшие проблемы.\n\n### 2. Схемный контроль скоростных шин PCI Express\nШина PCIe передает данные по дифференциальным парам со скоростями до 32–64 ГТ/с (PCIe 4.0/5.0/6.0):\n1. На канальном уровне (Data Link Layer) к каждому пакету TLP прикрепляется 32-битный код **LCRC (Link CRC)** и порядковый номер пакета Sequence Number.\n2. Приемник вычисляет LCRC:\n   - Если код совпал — передатчику отсылается короткий пакет подтверждения `Ack`.\n   - Если код не совпал — отсылается пакет `Nak`.\n3. Аппаратный блок передатчика автоматически извлекает сбойный пакет из своего буфера повтора (Replay Buffer) и **повторно передает его в шину**. Процесс происходит аппаратно за доли микросекунды совершенно незаметно для операционной системы!",
        "intuitSourceRef": "https://intuit.ru/studies/courses/tesvt"
