        "content": "# Лабораторная работа № 10 «Исследование методов восстановления операционной системы»\n\nЛабораторная работа посвящена методам программной реанимации и устранения критических сбоев операционных систем семейства Windows:\n\nВ ходе работы студенты осваивают:\n- Использование среды восстановления Windows Recovery Environment (WinRE);\n- Восстановление загрузочных конфигурационных записей UEFI: утилиты `bcdedit`, `bootrec /fixmbr`, `bootrec /rebuildbcd`;\n- Проверка и восстановление целостности системных файлов с помощью утилит `sfc /scannow` и `dism /online /cleanup-image /restorehealth`;\n- Настройка и анализ аварийных дампов памяти ядра (Memory Dump) при падении системы в BSOD с помощью отладчика Microsoft WinDbg;\n- Локализация сбойного системного драйвера по трассировке стека вызовов (`!analyze -v`).",
